t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "Lleva la {object:149047} hacia el sur por el borde de La Caldera y enciende los cuatro Braseros de centinela, del suroeste al sureste.",
		["Class trainer"] = "Instructor de clase",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "Para {npc:8256} en {zone:1455}, al final de esta guía",
		["Four rune rubbings in {zone:1447}: keep it"] = "Cuatro calcos de runas en {zone:1447}: guárdala",
		["Golems and elementals"] = "Gólems y elementales",
		["Greater Lava Spiders"] = "Arañas de lava abrasadoras",
		["Listen to {npc:8479}'s story once more."] = "Escucha la historia de {npc:8479} una vez más.",
		["Sentry Braziers"] = "Braseros de centinela",
		["The Grimesilt outhouse"] = "La letrina de Limugre",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "El elfo de la noche está solo al oeste de {area:1446}. Escucha su historia.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La siguiente tarea del prisionero, El libro de contabilidad de {zone:1446}, te envía a {zone:1435} y {zone:1445}: omítela.",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "El {object:149502} que te da contiene una {item:10575}: guárdala para {npc:9459}, en {zone:1428}",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["To {area:2101}"] = "A {area:2101}",
		["Xiggs waits in the {object:32359}."] = "Xiggs espera en el Distrito Militar ({object:32359}).",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} se abre en el norte de La Caldera. Los planos secretos están en su cornisa superior; los Incendosaurios nadan en las charcas de lava más adentro, así que atráelos hasta el borde. Mantente lejos de {npc:14621} y sus guardias élite del fondo.",
		["{npc:8509} and the dragonflight's hoard are beside {npc:8479}, on the rim south of {area:1446}."] = "{npc:8509} y el tesoro del Vuelo Negro están junto a {npc:8479}, en el borde al sur de {area:1446}.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: los mocos están en {zone:1448}, guárdala",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} está en el suelo a los pies de {npc:8479}; {quest:3462} está a su lado.",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462}: entrégala de camino de vuelta a {area:1446}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Bones and equipment"] = "Huesos y equipo",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Los huesos de dinosaurio ({item:11114}) están en el suelo del suroeste, entre los estegodones: son élite, así que recoge los huesos a su alrededor y consigue el resto de los diemetradones. El {item:11112} de la expedición está en la jungla del suroeste.",
		["Eastern Pylon"] = "La Torre del Este",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina con {npc:9298} en {zone:1452}: guárdala",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775} en {zone:1444}: guárdala",
		["Lar'korwi Mates and the raft"] = "Amigos de Lar'korwi ({npc:9683}) y la balsa",
		["Northern Pylon"] = "La Torre del Norte",
		["Pterrordax"] = "Pterrordáctilo",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Cabalga al este hasta {area:1943}, donde el robot está entre los gorilas. No entres en la cueva profunda de allí.",
		["Ride north along the western jungle back to the refuge."] = "Cabalga al norte por la jungla del oeste de vuelta al refugio.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Cabalga al sur hasta {area:537}, en el centro del cráter, y luego al este hacia la jungla del este. Hay grupos de cristales por todo el cráter, muchos alrededor de {area:537}: coge unos cuantos de más de cada color. Los latigadores pétalo de sangre ({npc:6509}) y los trilladores sueltan los pétalos; el {item:11113} de la expedición está en un campamento abandonado de la jungla del este.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Sal de {area:976} cabalgando al oeste hasta la larga rampa que baja a {zone:1449}. {npc:9619} acampa al pie de la rampa, en la esquina sureste del cráter.",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Los amigos de Lar'korwi ({npc:9683}) merodean por la jungla al oeste de {npc:9619}. La balsa naufragada está en la orilla del lago; el pequeño fardo está en el agua a su lado. Guarda la brújula, el mapa y la llave para {npc:8737}. Cualquier bestia del cráter puede soltar {item:11116}: haz clic derecho en él.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "El trillanodonte muerto yace junto al agua, al norte de {npc:9619}.",
		["The gorillas on {area:1943} carry the pelts: keep it for the second Un'Goro visit, around 56"] = "Los gorilas de {area:1943} llevan las pieles: guárdala para la segunda visita a Un'Goro, hacia el nivel 56",
		["The pylon stands on the eastern cliffs."] = "La torre está en los acantilados del este.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "La torre está en los acantilados del oeste. Los {npc:9167} vuelan por todo el lado oeste.",
		["The {zone:1455} quests were taken at the end of the {zone:1427} guide: fly straight on to {zone:1440} for {zone:1447}."] = "Las misiones de {zone:1455} se cogieron al final de la guía de {zone:1427}: vuela directamente a {zone:1440} para ir a {zone:1447}.",
		["To {area:2101}"] = "A {area:2101}",
		["Western Pylon"] = "La Torre del Oeste",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:537} and the eastern jungle"] = "{area:537} y la jungla del este",
		["{area:541} flight master"] = "Maestro de vuelo de {area:541}",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc en {zone:1447}, guárdala",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, al fondo del refugio",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} está justo fuera del refugio.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, en la entrada del refugio",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus está junto al rey Magni en {object:171709}.",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Archesonus está junto al rey Magni en {object:171709}: las reliquias que leíste en las Estepas son suyas.",
		["Ardalan is inside {area:1438}."] = "Ardalan está dentro de {area:1438}.",
		["Below ground"] = "Bajo tierra",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Sube a la cima de {area:249} y planta la cabeza en el montículo de tierra blanda.",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Termina con {quest:4808} en {area:2255}, {zone:1452}: guárdala",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Sigue el camino al oeste y luego sube al norte hasta el campamento goblin en {area:251}.",
		["For {zone:1453}: keep it"] = "Para {zone:1453}: guárdala",
		["Listen to his tale, then ride back south to Kum'isha."] = "Escucha su historia y luego vuelve al sur hasta Kum'isha.",
		["Mosshoof Coursers"] = "Maledictores Pezuñamusgo ({npc:8761})",
		["Open the {item:10569} from {zone:1427} for its {item:10575}, then tell {npc:9459} you bring proof of your deeds: no drake to fight."] = "Abre el {item:10569} de {zone:1427} para sacar su {item:10575} y luego dile a {npc:9459} que traes pruebas de tus hazañas: no hay que luchar contra ningún dragón.",
		["Portal to {zone:1438}"] = "Portal a {zone:1438}",
		["Ride back east along the road to the Vigil."] = "Vuelve al este por el camino hasta la Vigilia.",
		["Ride back south to the camp."] = "Vuelve al sur hasta el campamento.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Cabalga al norte desde {zone:1419} hasta {zone:1435}: el {npc:10996} está junto al camino que viene de {zone:1419}. Mantente alejado de {area:75}, el pueblo de la Horda al noreste.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Cabalga al noreste desde el santuario: {npc:8405} acampa en {area:1224}, en las colinas sobre el camino.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Nada hasta la islita frente al extremo sur de {zone:1447}. Si {npc:8392} no está allí, dispara tu {item:10444} para avisarle y espera a que aterrice.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Los ogros Pirontraña ocupan la gran roca al norte de la Vigilia, con los toscos en su lado este.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Los fantasmas altonatos rondan las ruinas alrededor del santuario; los sátiros Haldarr ocupan el campamento justo al norte.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Las nagas Látigo de Ira de las {area:1221} llevan {item:13815}. Las cuatro runas de {npc:8507} están entre las ruinas: usa su {item:10445} en cada una.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Los maledictores Pezuñamusgo ({npc:8761}) más cercanos pastan en las colinas al noreste de {area:1224}, hacia {area:1219}; una manada mayor recorre el terreno abierto del sur.",
		["The portal in {area:702} leads up to {zone:1457}: {npc:9047} waits in the {area:1658}, in the north of the city."] = "El portal de {area:702} sube a {zone:1457}: {npc:9047} espera en el {area:1658}, en el norte de la ciudad.",
		["The relics are in the {zone:1428}: keep it"] = "Las reliquias están en {zone:1428}: guárdala",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "El santuario está en la esquina suroeste de {zone:1447}, al sur de {area:3137}.",
		["The wildkin are in {zone:1452}: keep it"] = "Los lechúcicos están en {zone:1452}: guárdala",
		["The {area:1221}"] = "Las {area:1221}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the {zone:1425} shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Son bichos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:7977} (élite de nivel 48) requiere un grupo de 2. Sáltatela si vas solo: la ruta te hace recuperar la experiencia matando bichos.\n{npc:7977} recorre la orilla de {zone:1425} bajo {area:307}, desde la flecha al sur hasta aprox. 75,66 y al norte hasta aprox. 82,52: si no está en la flecha, sigue la orilla.",
		["To {area:2101}"] = "A {area:2101}",
		["Wildkin feathers"] = "Plumas de lechúcico",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:199} cauldron"] = "Caldera de {area:199}",
		["{item:10575}, from the hoard"] = "{item:10575}, del tesoro",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: los {npc:7864}, un 10 % aprox.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "El fantasma de {npc:10778} vaga junto a la casa de {area:199}, al oeste de {area:200}; su paquete está dentro.",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} protege la caldera de {area:199}, al oeste de Andorhal.",
		["{npc:8395} wants two Undamaged Hippogryph Feathers from the Thunderhead hippogryphs around his camp, the ones you top up on here: about one in three carries one."] = "{npc:8395} quiere dos plumas de hipogrifo sin estropear de los hipogrifos Cabeza de Trueno alrededor de su campamento, los mismos con los que subes de nivel aquí: aproximadamente uno de cada tres lleva una.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} acampa en {area:1219}, en el norte; su equipo está repartido por todo el {area:1220}, justo al sureste de él.",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, en el {area:1658}",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: los orcos Roca Negra sueltan los medallones, mantenla abierta por todas las Estepas",
		["{zone:1455} has no druid trainer"] = "{zone:1455} no tiene instructor de druidas",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Ends in the {zone:1413}: keep it"] = "Termina en {zone:1413}: guárdala",
		["First crater"] = "Primer cráter",
		["Five feathers buy a little Timbermaw reputation"] = "Cinco plumas dan un poco de reputación con los Fauces de Madera",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Sigue el camino al norte hasta la entrada de la cueva de {area:1769}; {npc:15395} la vigila.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Sigue el camino al norte hasta el valle de cráteres y ve a cada cráter, matando las bestias entrópicas y los horrores entre ellos.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa está en la salida de {zone:1452} del túnel: guárdala",
		["Second crater"] = "Segundo cráter",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Los fúrbolgs Muertobosque viven en el poblado justo al suroeste de {npc:11554}; guarda las plumas de penacho Muertobosque que sueltan.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Los antárboles Combadera de {area:1767}, al este de {area:2618}, llevan el {item:11503}.",
		["The {area:2479}"] = "El {area:2479}",
		["Third crater"] = "Tercer cráter",
		["{area:1763} again"] = "{area:1763} otra vez",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} es el valle de sátiros del noroeste, con {npc:10648} al fondo. Él suelta la {quest:939}; cualquier sátiro Fuego de Jade puede soltar {item:11674}.",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} espera en el extremo norte de {zone:1448}",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, en las ruinas justo al este de {npc:11554}",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Fly to Theramore"] = "Vuela a Theramore",
		["Fly to {area:3197}"] = "Vuela a {area:3197}",
		["Follow the road east across the zone to the chapel."] = "Sigue el camino al este cruzando la zona hasta la capilla.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Sigue el camino al oeste hasta el campamento de {npc:9298}, junto a las aguas termales.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Sigue el camino del sur hacia el este hasta {zone:1423}; las ruinas de {area:2262} están al sur. El fantasma de {npc:10926} juega junto a la casa en ruinas del extremo sur.",
		["For Kernda in {area:1769}: keep it"] = "Para Kernda en {area:1769}: guárdalo",
		["Free Darrowshire Spirits: talk to them"] = "Libera espíritus de Villa Darrow ({npc:11064}): habla con ellos",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Los yetis Cardo Nevado viven en las colinas al sur de {area:2244}, y las Quimeras venfresco en el valle hacia {area:2255}.",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Guárdalo: Gregan, en {zone:1444}, prepara el elixir más adelante",
		["On {npc:10978}, by the inn"] = "Sobre {npc:10978}, junto a la posada",
		["Pristine Yeti Horns"] = "Cuernos de yeti prístinos",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "Puracorazón, Dumah, Puño de Valor y MacDonnell están por el centro del campamento, junto al maestro de vuelo.",
		["Scare {npc:10978} with {item:12928}"] = "Asusta a {npc:10978} con {item:12928}",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "El caldero Muertobosque de {zone:1448}: guárdalo",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "El poblado de los fúrbolgs Nevada está al este de {area:2255}: chamanes (56-57), vigilantes del cubil (55-56) y ursas (57-58), todos por encima de ti. Mata primero a los chamanes, que curan, y atrae desde el borde. {npc:10738}, en la cueva del fondo, es élite: no entres.",
		["The next guide starts here and flies to {area:3197}."] = "La siguiente guía empieza aquí y vuela a {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Las ruinas rodean el lago helado al sur de {area:2253}. Recoge los cuatro fragmentos de reliquia que hay en las ruinas y las Plumas Lunadón del suelo, donde merodean los lechúcicos.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Las tres piezas de la muñeca están en las casas en ruinas de {area:2262}; al recoger una pueden aparecer fantasmas. Combínalas para formar la muñeca.",
		["To {area:2101}"] = "A {area:2101}",
		["Your Hearthstone is not set at {area:144} (the {zone:1425} guide binds there at 47, and this guide leaves {zone:1452} through it): bind at {area:2255} instead, for the trips back to town."] = "Tu piedra de hogar no está vinculada en {area:144} (la guía de {zone:1425} te vincula allí a nivel 47, y esta guía sale de {zone:1452} pasando por allí): vincúlala en {area:2255}, para los viajes de vuelta al pueblo.",
		["Your Hearthstone is still set at {area:144}: from there the gryphon to {area:3197} is about ten minutes quicker than {area:2255}'s flight to Theramore and the boat."] = "Tu piedra de hogar sigue vinculada en {area:144}: desde allí, el grifo a {area:3197} es unos diez minutos más rápido que el vuelo de {area:2255} a Theramore y el barco.",
		["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "Zaeldarr es élite: se recomienda ir en grupo. Espera al fondo de {area:2261}, la cripta del suroeste de la zona.",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:2255}'s inn"] = "La posada de {area:2255}",
		["{npc:10926}'s doll"] = "La muñeca de {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} y {npc:10977} vienen después",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: las termitas vienen más tarde, en {area:2627}",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, en {zone:1422}: guárdala",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Vuelve al campamento de {npc:7775}, justo al sureste de {npc:7765}: la {item:11242} te da tres Elixires de Videre. Guárdalos: {npc:9298} se queda uno, y {npc:9299} en {area:976} solo se muestra a quien haya bebido uno.",
		["Below ground"] = "Bajo tierra",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Cruza el río hacia el este hasta {area:2261}, la cripta del suroeste de la zona. El {object:177667} está dentro: la llave la lleva {npc:12248}, en el extremo noreste, que se hace en la siguiente guía.",
		["Cross the river west to {npc:1855}'s hut."] = "Cruza el río hacia el oeste hasta la cabaña de {npc:1855}.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Cruza el sur del cráter hasta {npc:9619}, junto a la rampa.",
		["Diseased Grizzlies"] = "Griseznos malsanos",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Los trituradores de arrastre excavan más al oeste; los tenazarios Latigosólido, cazadores Latigosólido y acechadores de piedra cazan en las mismas arenas.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Los artilleros de arrastre excavan en las dunas al noroeste del fuerte; los escórpidos Latigosólido y los arácnidos de arena deambulan por todas partes.",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina con {npc:9298} en {zone:1452}: guárdala",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Vuela de {area:976} a {area:541}. {npc:8737} está al fondo del refugio; {npc:9117} está en la cueva detrás de él.\n{npc:9999}, amigo de {npc:9997}, ha desaparecido.",
		["Fly to Theramore"] = "Vuela a Theramore",
		["Fly to {area:2268}"] = "Vuela a {area:2268}",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["For the druids of {zone:1457}: keep it"] = "Para los druidas de {zone:1457}: guárdala",
		["For {area:3197}: keep it"] = "Para {area:3197}: guárdala",
		["For {zone:1448}: keep it"] = "Para {zone:1448}: guárdala",
		["For {zone:1451}: keep it"] = "Para {zone:1451}: guárdala",
		["From {area:702}, fly to {area:1116}."] = "Desde {area:702}, vuela a {area:1116}.",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "El cráneo de Horgus está en {area:2624} y la espada de Marduk en {area:2623}, cada uno donde luchan fantasmas; los canes de la Peste adultos cazan en las llanuras de en medio.",
		["Into {zone:1451}"] = "Hacia {zone:1451}",
		["Listen to his story"] = "Escucha su historia",
		["Mark {npc:10902} with the {item:12815}"] = "Marca la {npc:10902} con la {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marca la {npc:10903} con la {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marca la {npc:10904} con la {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marca la {npc:10905} con la {item:12815}",
		["More watches"] = "Más relojes",
		["Northern Pylon"] = "La Torre del Norte",
		["On {npc:7583}"] = "Con {npc:7583}",
		["Portal to {zone:1438}"] = "Portal a {zone:1438}",
		["Radley and Durgen"] = "Radley y Durgen",
		["Ranshalla in {zone:1452}: keep it"] = "Ranshalla en {zone:1452}: guárdala",
		["Ride back south to the camp."] = "Vuelve al sur hasta el campamento.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Cabalga de vuelta al suroeste hasta la torre de {area:2742} en {area:2738}; súbela y mata a los emboscadores que surgen por el objeto incrustado.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Cabalga al este hasta el río de la frontera: {npc:1855} vive en una cabaña pequeña en la orilla.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Cabalga al este hasta {area:537}, súbela y usa {npc:10541} en las grietas de lava cerca de la cima.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Cabalga al norte por el lado este hasta la meseta de los gorilas. {npc:9622}, un gorila de nivel 55, está en su cueva más profunda: limpia primero los gorilas de la entrada.",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Cabalga al norte hasta {area:2627}. {npc:12384} vive en la choza en ruinas y su libro de recibos está en la posada en ruinas cercana.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Cabalga al norte por el camino hasta el Aserradero Crestanorte; {npc:11610} se esconde en el borde del campamento.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Cabalga al noroeste hasta la granja de Dalson. El diario está en el granero; un esqueleto errante lleva la llave del retrete, y {npc:10836} espera en el retrete con la llave del armario.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cabalga al noroeste hasta {area:2276}, en el borde de {area:2277}.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Cabalga al sur hasta {area:201}, donde {npc:11078} protege la caldera.",
		["Ride south-west to the camp."] = "Cabalga al suroeste hasta el campamento.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Cabalga al suroeste hasta el campamento de {npc:7771} en el {area:1938}.",
		["Ride west along the road to the hot springs."] = "Cabalga al oeste por el camino hasta las fuentes termales.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Cabalga al oeste hasta las Ruinas de Viento Cuervo: {npc:7774} se esconde en el pequeño edificio redondo del fondo. Abre el cofre junto a ella para obtener {item:9189}: dura 15 minutos, igual que la misión.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Cabalga al oeste hasta {area:2627}. Los cachorros de can de la Peste ({npc:8596}), los murcipestes ({npc:8600}) y las larvas carroñeras ({npc:8603}) rondan sus bosques; llena la {item:15042} en los grandes termiteros y mata a los canes de la Peste demenciados ({npc:8598}) más al norte.",
		["Scare {npc:7583} with {item:12928}"] = "Asusta a {npc:7583} con {item:12928}",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Toma el barco al continente y cabalga al noreste hasta el campamento de {npc:14637} junto a {area:1119}.",
		["Ten {item:11040} from the {item:11020}"] = "Diez {item:11040} de la {item:11020}",
		["The Andorhal watchtowers"] = "Las atalayas de Andorhal",
		["The Scarlet Crusade"] = "La Cruzada Escarlata",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Los médicos, cazadores, caballeros y magos escarlata patrullan el aserradero y el camino hacia {area:190}.",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "Las bestias de alquitrán y los señores del alquitrán se revuelcan en {area:538}, al sur del refugio, en la bajada al cráter.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "La caldera está en {area:202}, junto a la granja de {npc:10739}.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "La caldera está en {area:200}, al noreste de Piedramácula; su señor de la caldera está a su lado.",
		["The crater"] = "El cráter",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Los gorilas viven en {area:1943}, justo al este de la torre: consigue ahora las pieles para {npc:9619}, ya que estás aquí arriba. No entres en la cueva más profunda: {npc:9622} es de nivel 55.\nCuidado: los gorilas de Un'Goro (nivel 50-51) piden ayuda a los aliados en un radio de 20 m cuando bajan al 25% de salud. Hay una cueva llena de simios en la zona, y luchar allí atrae a muchos enemigos.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Los gigantes encogidos rondan {area:1119}; los elementales marinos vadean la costa al oeste.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Los druidas y centinelas torturados rondan el poblado en ruinas al suroeste de {npc:13220}.",
		["The wooden sign beside {npc:9997}"] = "El cartel de madera junto a {npc:9997}",
		["The {area:2742} tower"] = "La torre de {area:2742}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "La {item:11242} crece dentro de un edificio en ruinas al norte de {npc:7765}: entra por la brecha de su muro desde la cornisa de al lado.",
		["Umber in {zone:1450}: keep it"] = "Umber en {zone:1450}: guárdala",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Usa el {item:12627} junto a los silos de grano para hacer salir parásitos temporales. {quest:5154} es uno de los tomos mohosos del ayuntamiento. Todos los esqueletos del pueblo sueltan {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Usa la {item:12815} al pie de cada una de las cuatro atalayas del borde de Andorhal, al norte del campamento.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "Entra en {area:1769} y toma el ramal del túnel de {zone:1450} hasta {area:2361}.",
		["{area:190} overlook"] = "Mirador de {area:190}",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: mata a estos según los encuentres",
		["{area:200} cauldron"] = "Caldera de {area:200}",
		["{area:201} cauldron"] = "Caldera de {area:201}",
		["{area:202} cauldron"] = "Caldera de {area:202}",
		["{item:12894}, at the monument"] = "{item:12894}, en el monumento",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "El {item:12954} está en el ayuntamiento de {area:190}, al oeste de {npc:1855}: los guardias escarlata están muy juntos.",
		["{item:12955} lies east of the barn at {area:201}."] = "El {item:12955} está al este del granero de {area:201}.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} espera en la posada en ruinas del lado oeste de Andorhal.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} y {npc:7740} están junto al Templo de la Luna; llena el {item:11682} en el pozo de la luna de dentro.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "La granja de {npc:10927} está en la colina al este del campamento; el monumento de {npc:10936} está justo al norte.",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} es élite: conviene ir en grupo",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, en las tiendas de la Alianza",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} es élite de nivel 61",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} en {area:976}: guárdala",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, en la costa al norte del pueblo",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: guárdala para {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He brews the {item:11243} from an {item:11242}: take his errand for one."] = "El campamento de {npc:7775} está al norte de {area:1119}. Prepara el {item:11243} a partir de una {item:11242}: acepta su encargo para conseguir uno.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: guárdala para {zone:1446}",
		["{npc:9299} in {area:976}: keep it"] = "{npc:9299} en {area:976}: guárdala",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299} es un fantasma en el cementerio justo al este del pueblo: bebe un {item:11243} allí, lo que te mata, libera tu espíritu y habla con él como fantasma. Luego corre de vuelta a tu cuerpo para resucitar: la lápida está cerca.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "La guarida de {npc:9684} está en la jungla al norte de {npc:9619}, bajo los acantilados del este: usa {item:11568} allí. {npc:9684} es de nivel 56: empieza con la salud al máximo.",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} está sentado en la ladera sureste de {area:537}, en el centro del cráter.",
		["{quest:3444} is in {area:392}"] = "{quest:3444} está en {area:392}",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, en {area:2268}: guárdala",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} en {zone:1450}: guárdala",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, donde se entrena en la siguiente guía, no tiene instructor de druidas",
} end)()
