t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Angerclaw bears and Felpaw wolves"] = "Osos Zarpira y lobos Zarpayel",
		["Araj is elite: grouping up is advised."] = "Araj es élite: se recomienda ir en grupo.",
