		["{npc:1231}, at the smithy"] = "{npc:1231}, en la herrería",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427} está arrodillado y herido en la loma entre dos muros bajos justo al sur de {area:131}, al otro lado del camino del instructor de mascotas de cazador, de vuelta del campamento de Rumbleshot. Lánzale {spell:613} (rango 2) y después {spell:1243}: el rango 1 de {spell:613} no cuenta.",
		["{npc:12738}, next to him"] = "{npc:12738}, a su lado",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: con tiempo límite, cinco minutos para llegar con {npc:836} en {area:77}",
