		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} está en la torre de los magos de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: la recoge {npc:6122} en {zone:1453}",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, al lado de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "El campamento de {npc:714} está en el extremo oeste del valle. La {item:10438} está en la nieve al sur, su cofre junto a la cueva de los trols y su cubo de tornillos al este de la cueva: cógelos al pasar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} y {npc:12738} acampan en el borde suroeste del valle, bajo la cueva de los trols.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro de la cueva de los trols al este del campamento de {npc:786}, no en la colina de encima: entra por la boca y sigue el túnel hasta el fondo.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, el instructor de sacerdotes",
		["{npc:912}, the warrior trainer"] = "{npc:912}, el instructor de guerreros",
		["{npc:916}, the rogue trainer"] = "{npc:916}, el instructor de pícaros",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, el instructor de magos, dentro de {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, junto al buzón de {object:171524}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tía\" Bernice Pedregosa",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Vuelve con {npc:6122} el Vinculaoscuro. Usa el {item:6928} en el círculo de invocación del sótano de {object:2164} y derrota al abisario que aparece.",
		["Billy plays in the {area:64}, east of the mine."] = "Billy Maclure juega en {area:64}, al este de la mina.",
		["Chunks of Boar Meat"] = "Trozos de carne de jabalí",
		["Class trainer"] = "Instructor de clase",
		["Crystal Kelp Fronds"] = "Hojas de kelp de cristal",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Los Zahoríes bribones Defias acampan en las orillas de {area:86}; también sueltan los Pañuelos de lino rojo. {object:56} está en el poblado múrloc de la orilla noreste.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Los Matones Defias acampan en el claro al este de la abadía y por el lado este del valle.",
		["Follow the hills south to the tower, on the road west."] = "Sigue las colinas hacia el sur hasta la torre, en el camino al oeste.",
		["Follow the hills south to the tower."] = "Sigue las colinas hacia el sur hasta la torre.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Sigue el sendero hacia el norte hasta la mina. Los Trabajadores kóbold pululan fuera; cualquier kóbold del valle puede soltar {object:83763}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:5497} está en el Sagrario del Mago, la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Sigue el camino hacia el sur, fuera de {area:87}, hasta {area:64}. {npc:251} Maclure espera junto a la casa.",
		["Fun with Elementals: {npc:248464}"] = "Álbum de fotos: diversión con elementales: {npc:248464}",
		["He stands by the river west of the farm."] = "Está junto al río, al oeste de la granja.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Regresa por {area:87} y hacia el este por el camino hasta {area:62}. {npc:881} (nivel 9) está junto a la granja.",
		["Heal and fortify {npc:12423}"] = "Sana y fortalece a {npc:12423}",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Está junto al río, al noroeste del campamento maderero.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "Los Obreros kóbold trabajan en los túneles de la mina. {npc:248362} espera tras el segundo giro a la derecha.",
		["Large Candles"] = "Velas grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena {item:7207} al pie de ella.",
		["Lost Books: Kobold Miners and Tunnelers"] = "Libros perdidos: Mineros kóbold y Tuneladores",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Los múrlocs y los Correcorrientes múrloc ocupan la orilla este; los Montones de chatarra están en su campamento. Cuidado: los múrlocs están muy juntos, así que es fácil atraer a dos o tres a la vez en un combate: atráelos de uno en uno desde el borde del campamento y no persigas a ninguno hasta el siguiente grupo.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "Al noreste del campamento maderero. Los Zahoríes bribones Defias acampan en las orillas del lago.",
		["Painted Gnoll Armbands"] = "Bandas gnoll pintadas",
		["Red Burlap Bandanas"] = "Arpilleras rojas",
		["Red Linen Bandanas"] = "Pañuelos de lino rojo",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Los gnolls Zarparrío acampan en las colinas al oeste de {area:86}; {quest:91725} están en sus campamentos.",
		["She stands by her cart at the vineyard east of the Abbey."] = "Está junto a su carro, en el viñedo al este de la abadía.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Está fuera, en la entrada de la mina. {npc:248362}, dentro, es élite: se recomienda ir en grupo.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Manzanas rojas lustrosas, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Siéntate (/sentarse) junto a su hoguera hasta tener {spell:1229451}",
		["South down the road to the {area:64}."] = "Al sur por el camino hasta {area:64}.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["The Defias camp"] = "El campamento Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Las trampas de pesca ({object:694772}) están en la orilla oeste del lago.",
		["The bridge"] = "El puente",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "El campamento está al noreste del puente. Los Fajos de madera están alrededor del campamento y en el bosque al norte.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Las cajas de uvas están en los viñedos, detrás de los Defias. {npc:103} espera junto a la cabaña del extremo este del valle.",
		["The gnoll camps"] = "Los campamentos gnoll",
		["The kobold camp"] = "El campamento kóbold",
		["The lake shore"] = "La orilla del lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "La mina está al suroeste de los campamentos gnoll. {item:247816} están cerca de la entrada; los Geománticos kóbold ocupan los túneles.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mina está al oeste de los viñedos. Los Mineros kóbold y los Tuneladores llenan ambos niveles; {npc:248464}, un kóbold con nombre, tiene el álbum de fotos en los túneles inferiores. {npc:248464} es élite: se recomienda ir en grupo.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Los múrlocs de la orilla este sueltan el kelp. Desolladores: los Lobos grises del bosque recorren el bosque entre el lago y {area:91}; los Merodeadores, más al este, también dan pieles.",
		["The vineyards and {npc:103}"] = "Los viñedos y {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {quest:91736}"] = "{quest:91736}",
		["Walk into the mine"] = "Entra en la mina",
		["Walk through the mine"] = "Recorre la mina",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Empiezas delante de la abadía. {npc:823} está al pie de la escalinata; {npc:197}, dentro de la sala; {npc:951} y {npc:247229}, en la biblioteca de la derecha; {npc:196}, fuera, en la esquina noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Los Lobos jóvenes y los Lobos madereros recorren los campos junto a la abadía.",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "su rastreador de kóbolds muestra los kóbolds en los que hacer clic en el camino a {area:87}",
		["talk to the trainer"] = "habla con el instructor",
		["{item:247824}, from the still"] = "{item:247824}, del alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Jabalíes colmillopétreo",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} del campamento Defias",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} está arrodillado y herido junto a un árbol en la orilla oeste de {area:18}, entre las trampas de pesca. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se marcha cuando recibe ambos y vuelve en unos 3 minutos.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, junto a {npc:6306}",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: domestícalo con la {item:15908}",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, el instructor de magos, dentro de la abadía",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, en la Posada Orgullo de León",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} y {npc:248248} están al pie de la torre.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, junto a la abadía",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} está con los instructores de {area:87}. Cada una de sus misiones te da una {item:15908}: úsala en la bestia que te indique y devuélvele la vara. Los Jabalíes Ocultorroca y los Osos del bosque jóvenes recorren las colinas al sur de {area:64}; los Lobos grises del bosque, el bosque al este de {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, de vuelta en la posada",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, a su lado: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} vigila el puente del camino al este; {npc:248265} está justo al otro lado.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} acampa al noreste de la posada. Si has aprendido una profesión, también ofrece su Acampada 101, que recibe su instructor: desuello, peletería y pesca en la orilla del lago; {skill:129} y herrería en {area:87}.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: para {npc:1632}, en la orilla del lago",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: para {npc:1651}, en la orilla del lago",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: para {npc:2329}, en la Posada Orgullo de León",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: para {npc:514}, en la herrería de {area:87}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: para {npc:6306}, en la orilla del lago",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279}, en {zone:1453}, lo recibe (02-westfall)",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: lo recibe {npc:5497}, en {zone:1453}",
		["{npc:375}, the priest trainer"] = "{npc:375}, la instructora de sacerdotes",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, la instructora de sacerdotes: lo recibe {npc:377}, en {area:87}",
		["{npc:377}, upstairs"] = "{npc:377}, en el piso de arriba",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, en el piso de arriba: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: sana a {npc:12423} en {area:18}",
		["{npc:459}, outside the Abbey"] = "{npc:459}, fuera de la abadía",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, en la herrería al otro lado del camino",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}, en la herrería junto a Dughan: lo recibe {npc:1416}, en {zone:1453} (02-westfall)",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: domestícalo con la {item:15908}",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: lo recibe {npc:6122}, en {zone:1453}",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, en la orilla del lago al este del pueblo; dentro",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} y {npc:1651} están en la orilla de {area:18}, al este del pueblo.",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, junto a los establos al sur de la abadía",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} excavan en los viñedos al noreste de la abadía. De vez en cuando uno suelta un {quest:91741}: haz clic derecho en él.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: domestícalo con la {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de vuelta en la escalinata de la abadía",
		["{npc:915}, the rogue trainer"] = "{npc:915}, el instructor de pícaros",
		["{npc:925}, the paladin trainer"] = "{npc:925}, el instructor de paladines",
		["{npc:952}, upstairs"] = "{npc:952}, en el piso de arriba",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: para {npc:234} en {area:108}",
		["{quest:76}'s entrance"] = "Entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} está dentro de {area:57}, no en la colina de encima: entra por la boca y ve por la izquierda hasta el fondo de la mina; no subas las escaleras. Los Bandidos Defias de los viñedos sueltan de vez en cuando una {item:1972}: haz clic derecho en ella.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} y {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sentarse junto a la hoguera de {npc:265811} hasta que tengas {spell:1229451}",
		["Back at {area:256}"] = "De vuelta en {area:256}",
		["Back to the moonwell."] = "Vuelve al pozo de la luna.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Vuelve a lo alto de {area:256}. El {object:654846} está a su lado.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Vuelve arriba con {npc:3567} con las arañas hechas y el musgo de {npc:272116}.",
		["Befouled Webwoods"] = "Tejemadera infectos",
		["Below ground"] = "Bajo tierra",
		["Bloodfeather harpies"] = "Arpías Plumasangre",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada misión de Dazalar te da una {item:15908}: úsala en la bestia que nombra y devuélvele la vara en {area:186}. Los rondadores Tejemadera merodean alrededor del poblado; los acechadores sable de la noche y los estridadores estrígidos recorren el bosque al sur.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolta a {npc:275744} fuera del túmulo; {npc:2081} en {area:186} recibe el informe.",
		["Fandral in {zone:1457} takes it"] = "La recibe Fandral en {zone:1457}",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Sigue el camino al suroeste desde {area:188}. {npc:2150} está sentado junto a él, justo al este de {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Los emboscadores Tuercepinos se esconden a lo largo del camino al oeste de {area:258}.",
		["Gnarlpine Shamans"] = "Chamanes Tuercepinos",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Vuelve a bajar a {area:702} y vuela a {area:442}. El {object:177525} está en las colinas justo al este del poblado: usa el {item:15208} allí, derrota a Lunaclaw y habla con el {npc:12144}.",
		["Heal and fortify {npc:12429}"] = "Cura y fortalece a {npc:12429}",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Sal de {area:188} por el sendero al sureste de {area:256}: {npc:6780} está a su lado, donde baja hacia el camino a {area:186}.",
		["Nightsabers"] = "Sables de la Noche",
		["North to {area:257}"] = "Al norte, hacia {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "Al noreste desde la guarida de Ursal, de vuelta a {area:186}.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "Al noroeste de Dolanaar, camino del {area:264}, los Tejemadera infectos merodean por el bosque; {npc:272116} ronda por su borde este y lleva el {item:281023}.\n{npc:272116} es élite (nivel 12): se recomienda ir en grupo. Despeja primero las arañas a su alrededor y atráelo a él solo.",
		["Sentinel Arynia again"] = "Centinela Arynia otra vez",
		["South from the glade toward Ursal: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Al sur desde el claro hacia Ursal: Shayla recorre el camino al oeste de {area:186}, desde donde lo cruza el sendero que baja del claro, al suroeste hasta la curva en torno a 38,54, y vuelta.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Al sureste de Dolanaar, hasta {npc:2080}. Los brotes azotadores deambulan a su alrededor en la orilla.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Al suroeste del túmulo. El pozo de la luna está junto a las charcas.",
		["Speak with the {quest:5929}"] = "Habla con el {quest:5929}",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Toma otra vez el camino al noroeste desde {area:186}; sigue tendida a su lado, camino de {zone:1457}.",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA a la puerta de la posada",
		["The moonwell"] = "El pozo de la luna",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "El pozo de la luna está en el centro del claro. La {object:6752} crece en su extremo norte.",
		["The named harpies"] = "Las arpías con nombre",
		["The road to {zone:1457}"] = "El camino a {zone:1457}",
		["The {area:478}"] = "El {area:478}",
		["The {object:177525}"] = "El {object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Los {object:4406} están al fondo de {area:257}: toma el sendero central, luego a la izquierda donde se divide, hasta la cornisa alta. Los grells sueltan champiñones jacinto; los lirios alunados crecen junto a las charcas al norte de {area:256}.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los corremareas corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los trilladores de la Costa Oscura nadan en las aguas poco profundas. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["Use the {item:18152} at the moonwell"] = "Usa la {item:18152} en el pozo de la luna",
		["Use the {item:5185} at the moonwell"] = "Usa la {item:5185} en el pozo de la luna",
		["Use the {item:5619} at the moonwell"] = "Usa la {item:5619} en el pozo de la luna",
		["Use the {item:5621} at the moonwell"] = "Usa la {item:5621} en el pozo de la luna",
		["Walk Lynessa out and keep her alive"] = "Saca a Lynessa y mantenla con vida",
		["Webwood Lurkers"] = "Rondadores Tejemadera",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Al oeste por el camino hacia la ciudad. Shayla recorre este tramo del camino, desde la flecha al suroeste hasta la curva en torno a 38,54, y vuelta: si no está en la flecha, sigue el camino al suroeste. Todos los fúrbolg Tuercepinos sueltan colmillos: cuentan los emboscadores de este camino, los del túmulo y los de {area:261}.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors."] = "Al oeste desde las arañas hasta el {area:265} y luego al norte por su curso hasta el claro: los brezomaderas de sus orillas sueltan los tumores musgosos.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Con una profesión aprendida, {npc:265811} también ofrece su Acampada 101, que recibe su instructor: alquimia y herboristería junto a {npc:6286}, {skill:129} con {npc:6094} en la posada, desuello y peletería en el campamento de los Tejecrín, en el camino al oeste.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Empiezas al pie de {area:256}, el gran árbol de {area:188}.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Los sables de la Noche jóvenes y los jóvenes jabalíes Cardo deambulan alrededor de {area:256}. Los grells llevan {item:3297} en el bosque al oeste del árbol, donde están los tótems Tuercepinos.",
		["talk to the trainer"] = "habla con el instructor",
		["{area:186} again"] = "{area:186} otra vez",
		["{area:258}'s mouth"] = "Entrada de {area:258}",
		["{area:736}, outside the barrow"] = "{area:736}, fuera del túmulo",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} de {npc:6736}, para {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} de {npc:3614}, junto a {npc:6094}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, en el Templo de la Luna: Fragmentos estelares",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} está arrodillada y herida en las rocas del borde norte de {area:259}, camino de vuelta a {area:186}, sin marca de misión encima. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se marcha en cuanto recibe ambos y vuelve en unos 5 minutos.",
		["{npc:1992}, south of the tree"] = "{npc:1992}, al sur del árbol",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: domestícalo con la {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: domestícalo con la {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} espera dentro de la cueva, abajo o arriba en la cornisa; ve por la derecha.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: domestícalo con la {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, junto al sendero",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: un sigilo para {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: la recibe {quest:922} en {zone:1457}",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, en la rampa del árbol",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrulla el camino al oeste de la aldea: si no está en la flecha, sigue el camino hasta encontrarla.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, en el camino al oeste del poblado",
		["{npc:265811}, by the campfire"] = "{npc:265811}, junto a la hoguera",
		["{npc:265811}: for {npc:3603}, beside {npc:6286}"] = "{npc:265811}: para {npc:3603}, junto a {npc:6286}",
		["{npc:265811}: for {npc:3604}, beside {npc:6286}"] = "{npc:265811}: para {npc:3604}, junto a {npc:6286}",
