		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Vuela a {area:1237} si lo tienes, si no a {area:431}, y camina al este desde {zone:1440} hasta {zone:1447}.",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Vuela a {area:3137} si lo tienes, si no a {area:415}, y camina al este desde {zone:1440} hasta {zone:1447}.",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Desde el oeste de {zone:1446}, baja por el sendero hasta {zone:1449}. {area:541}, en el norte, es un campamento neutral.",
